--   Still not convertible: smart_scripts (MangosFour has no SmartAI engine),
--   creature_text (no target table), locales_* (all empty in the source DB).
--
-- Safe to re-run (idempotent). Apply:
--   mysql -h 192.168.1.6 -u root -p mangos4 < 05_npc_gossip_events.sql
-- ============================================================================

