(21195,1,1,'I want to browse your goods',3,128,0,0,0,0,0,'',0),
(590,0,0,'Can you give me directions?',1,1,589,0,0,0,0,'',0),
(592,0,0,'Can you give me directions?',1,1,591,0,0,0,0,'',0),
(8365,0,0,'Alliance Battlemasters',1,1,8408,0,246,0,0,'',0),
(8365,1,0,'Horde Battlemasters',1,1,8409,0,247,0,0,'',0),
(6500,0,9,'I wish to join the battle!',12,1048576,0,0,0,0,0,'',0),
(21248,0,0,'Search the body for the pilot''s emergency toolkit.',1,1,0,0,0,0,0,'',0),
(6510,0,9,'I wish to join the battle!',12,1048576,0,0,0,0,0,'',0),
(6492,0,9,'I wish to join the battle!',12,1048576,0,0,0,0,0,'',0),
(21251,0,0,'Sprinkle some of the reindeer dust onto Metzen.',1,1,21252,0,0,0,0,'',0),
(10600,0,0,'Bring forth the first challenge!',1,1,0,0,0,0,0,'',0),
(10687,0,0,'Give the signal! We''re ready to go!',1,1,0,0,0,0,0,'',0),
(10688,0,0,'Val''kyr? We''re ready for them.',1,1,0,0,0,0,0,'',0),
(21253,0,0,'Private Weeks, I need another disguise.',1,1,0,0,0,0,0,'',0),
(21255,0,0,'I have a book that might interest you. Would you like to take a look?',1,1,21256,0,0,0,0,'',0),
(21256,0,0,'Thank you! I''ll be sure to notify you if I find anything else.',1,1,0,0,0,0,0,'',0),
(21257,0,0,'Let us consult the omens.',1,1,0,0,0,0,0,'',0),
(21258,0,0,'I think I have heard of this magic.',1,3,21259,0,0,0,0,'',0),
(21259,0,0,'Arcanum? That sounds very familiar.',1,3,21260,0,0,0,0,'',0),
(21260,0,0,'What are the components?',1,3,21261,0,0,0,0,'',0),
(21262,0,0,'Falthir, I need assistance in recovering a piece of my Madcap''s outfit.',1,3,21270,0,0,0,0,'',0),
(21262,1,0,'Falthir, I need assistance in recovering a piece of my Predator''s outfit.',1,3,21271,0,0,0,0,'',0),
(21272,0,0,'It is good to see the Burning Blade is taking over where the Shadow Council once failed.',1,1,21273,0,0,0,0,'',0),
(21273,0,0,'So the Searing Blade is expendable?',1,1,21274,0,0,0,0,'',0),
(21274,0,0,'If there is anything you would have of me...',1,1,21275,0,0,0,0,'',0),
(21276,0,0,'How did you know? I mean, yes... Yes I am looking for that shard. Do you have it?',1,1,21277,0,0,0,0,'',0),
(21277,0,0,'Alright. Where?',1,1,21278,0,0,0,0,'',0),
(21278,0,0,'By Bronzebeard''s... um, beard! What are you talking about?',1,1,21279,0,0,0,0,'',0),
(21279,0,0,'Fish? You gave a piece of what could be the key to saving all life on Kalimdor to a fish?',1,1,21280,0,0,0,0,'',0),
(21280,0,0,'A minnow? The oceans are filled with minnows! There could be a hundred million million minnows out there!',1,1,21281,0,0,0,0,'',0),
(21281,0,0,'...',1,1,21282,0,0,0,0,'',0),
(21282,0,0,'You put the piece on a minnow and placed the minnow somewhere in the waters of the sea between here and the Eastern Kingdoms? And this minnow has special powers?',1,1,21283,0,0,0,0,'',0),
(21283,0,0,'You''re insane.',1,1,21284,0,0,0,0,'',0),
(21284,0,0,'I''m all ears.',1,1,21285,0,0,0,0,'',0),
(21285,0,0,'Come again.',1,1,21286,0,0,0,0,'',0),
(21286,0,0,'Ok, let me get this straight. You put the scepter entrusted to your Flight by Anachronos  on a minnow of your own making and now you expect me to build an... an arcanite buoy or something... to force your minnow out of hiding? AND potentially incur the wrath of an Elemental Lord? Did I miss anything? Perhaps I am to do this without any clothes on, during a solar eclipse, on a leap year?',1,1,21287,0,0,0,0,'',0),
(21287,0,0,'FINE! And how, dare I ask, am I supposed to acquire an arcanite buoy?',1,1,21288,0,0,0,0,'',0),
(21288,0,0,'But...',1,1,0,0,0,0,0,'',0),
(21289,0,0,'I believe in you.',1,1,0,0,0,0,0,'',0),
(40060,0,0,'I present you with proof...',1,1,0,0,0,0,0,'',0),
(54000,0,0,'Lift the frost leopard''s tail to check if it''s a male or a female.',1,1,0,0,0,0,0,'',0),
(55000,0,0,'Lift the icepaw bear''s tail to check if it''s a male or a female.',1,1,0,0,0,0,0,'',0),
(21290,0,0,'I need answers, ogre!',1,1,21291,0,0,0,0,'',0),
(21291,1,0,'Why are the Boulderfist out this far? You know that this is Kurenai territory.',1,1,21292,0,0,0,0,'',0),
(21292,2,0,'And you think you can just eat anything you want? You''re obviously trying to eat the Broken of Telaar.',1,1,21293,0,0,0,0,'',0),
(21293,3,0,'This means war, Lump! War I say!',1,1,21294,0,0,0,0,'',0),
(21310,0,0,'I need a moment of your time, sir.',1,1,21311,0,0,0,0,'',0),
(21311,0,0,'Why... yes, of course. I''ve something to show you right inside this building, Mr. Anvilward.',1,1,0,0,0,0,0,'',0),
(21313,0,0,'There is only one Warchief, Eitrigg!',1,1,21314,0,0,0,0,'',0),
(21314,0,0,'What do you mean?',1,1,21315,0,0,0,0,'',0),
(21315,0,0,'Hearthglen? But...',1,1,21316,0,0,0,0,'',0),
(21316,0,0,'I will take you up on that offer, Eitrigg.',1,1,21317,0,0,0,0,'',0),
(21317,0,0,'Ah, so that is how they pushed the Dark Iron to the lower parts of the Spire.',1,1,21318,0,0,0,0,'',0),
(21318,0,0,'Perhaps there exists a way?',1,1,21319,0,0,0,0,'',0),
(21319,0,0,'As you wish, Eitrigg.',1,1,0,0,0,0,0,'',0),
(21248,1,0,'Search the body for the pilot''s insignia.',1,1,0,0,0,0,0,'',0),
(4464,0,3,'I would like to train further in the ways of the Light.',5,16,0,0,0,0,0,'',0),
(4464,1,0,'I wish to unlearn my talents.',16,16,4461,0,0,0,0,'',0),
(4464,2,0,'I wish to know about Dual Talent Specialization.',1,1,10371,0,0,0,0,'',0),
(3643,0,3,'I would like to train.',5,16,0,0,0,0,0,'',0),
(3643,1,0,'I wish to unlearn my talents.',16,16,4461,0,0,0,0,'',0),
(3643,2,0,'I wish to know about Dual Talent Specialization.',1,1,10371,0,0,0,0,'',0),
(21322,0,0,'My apologies, I did not realize that you could understand what I was saying. What is it you are doing out here?',1,1,21323,0,0,0,0,'',0),
(21323,0,0,'Do you? Perhaps you should tell me what it is that is bothering you',1,1,21324,0,0,0,0,'',0),
(21324,0,0,'What deal?',1,1,21325,0,0,0,0,'',0),
(21325,0,0,'So how did he break the deal?',1,1,21326,0,0,0,0,'',0),
(21326,0,0,'Perhaps I can be of some assistance. I will make a deal with you, Satyr. I shall recover this unforged breastplate and slay the beast. In exchange for this task, you will teach me how to create the breastplate',1,1,0,0,0,0,0,'',0),
(21330,0,0,'I''ve made no mistakes.',1,1,21331,0,0,0,0,'',0),
(21215,1,5,'Make this inn your home.',8,65536,0,0,0,0,0,'',0),
(21215,2,1,'I want to browse your goods',3,128,0,0,0,0,0,'',0),
(21215,0,0,'Trick or Treat!',1,1,0,0,0,0,0,'',0),
(21400,0,0,'I need a Cenarion beacon.',1,1,0,0,0,0,0,'',0),
(21400,1,0,'What plants are in Felwood that might be corrupted?',1,1,0,0,0,0,0,'',0),
(21331,0,0,'You have lost your mind, Nefarius. You speak in riddles.',1,1,21332,0,0,0,0,'',0),
(21332,0,0,'Please do.',1,1,0,0,0,0,0,'',0),
(21333,0,0,'I cannot Vaelastraz! Surely something can be done to heal you!',1,1,21334,0,0,0,0,'',0),
(21334,0,0,'Vaelastraz, no!!',1,1,21332,0,0,0,0,'',0),
(21335,0,0,'I am ready to fight alongside you, Akama.',1,1,0,0,0,0,0,'',0),
(14988,0,0,'I''m ready to go, General.',1,1,0,0,0,0,0,'',0),
(14224,0,5,'Make this inn your home.',8,65536,0,0,0,0,0,'',0),
(14224,1,1,'Let me browse your goods.',3,128,0,0,0,0,0,'',0),
(14379,0,3,'I seek training in Pandaren cooking.',5,16,0,0,0,0,0,'',0),
(14379,1,1,'I need supplies for cooking lessons.',3,128,0,0,0,0,0,'',0),
(14379,2,0,'I''m ready to discover the secret ingredient in the Lin family''s secret ingredient noodle soup!',1,1,0,0,0,0,0,'',0),
(13608,0,0,'I''ve got all this fruit here. Could you brew up some hooch for me?',1,1,0,0,0,0,0,'',0),
(13608,1,3,'I seek training in the Way of the Brew.',5,64,0,0,0,0,0,'',0),
(13609,0,0,'Chef, could you grill this plainshawk leg for me?',1,1,0,0,0,0,0,'',0),
